@Component
public class ShowCloser {                       // open unless you write final
    private final ShowArchive archive;

    public ShowCloser(ShowArchive archive) {
        this.archive = archive;
    }

    @Timed
    public String close(String night) {           // overridable
        verify(night);                            // self-call: intercepted in a subclass
        archive.file(night);
        return "closed " + night;
    }

    @Timed
    public void verify(String night) { /* ... */ }

    public final String hall() { return "Main hall"; }   // final on purpose: not intercepted
}

