public final class RecordInterceptor implements Interceptor {
    private final List<String> record;

    public RecordInterceptor(List<String> record) { this.record = record; }

    @Override
    public Object intercept(Invocation inv) {
        record.add(inv.getName() + Arrays.toString(inv.getArgs()));   // 1. write it down first
        return inv.proceed();                                        // 2. then pass it on
    }
}

